// One item per extracted entity, so the next node can search Zep for each.
const extraction = $input.first().json.output || {};
const entities = Array.isArray(extraction.entities) ? extraction.entities : [];
const norm = (s) => (s || '').toString().toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
if (!entities.length) {
  return [{ json: { name: '__none__', type: 'None', summary: '', norm: '__none__' } }];
}
return entities.map((e) => ({
  json: {
    name: (e.name || '').toString().slice(0, 120),
    type: (e.type || 'Concept').toString(),
    summary: (e.summary || '').toString().slice(0, 400),
    norm: norm(e.name),
  },
}));

// The upsert step: match extracted entities against existing graph nodes by
// normalized name. Matched entities reuse the existing node UUID (merge);
// unmatched ones will be created by Zep when the fact triple is written.
const entities = $('Plan Entity Lookups').all().map((i) => i.json);
const parseBody = (j) => {
  if (j && typeof j.data === 'string') {
    try { return JSON.parse(j.data); } catch { return {}; }
  }
  return j || {};
};
const searches = $input.all().map((i) => parseBody(i.json));
const extraction = $('Extraction Subagent').first().json.output || {};
const relationships = Array.isArray(extraction.relationships) ? extraction.relationships : [];
const cfg = $('Config').first().json;
const norm = (s) => (s || '').toString().toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const entityMap = {};
const entityReport = [];
for (let i = 0; i < entities.length; i++) {
  const e = entities[i];
  if (e.name === '__none__') continue;
  const found = ((searches[i] || {}).nodes || []).find((n) => norm(n.name) === e.norm);
  const resolved = {
    name: found ? found.name : e.name,
    uuid: found ? found.uuid : null,
    type: e.type,
    summary: e.summary,
    status: found ? 'merged' : 'new',
  };
  entityMap[e.norm] = resolved;
  entityReport.push(resolved);
}

const sanitizeRelation = (r) => (r || 'RELATED_TO').toString().toUpperCase().replace(/[^A-Z0-9_]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '').slice(0, 40) || 'RELATED_TO';

const triples = [];
for (const rel of relationships) {
  const s = entityMap[norm(rel.source)];
  const t = entityMap[norm(rel.target)];
  const sourceName = s ? s.name : (rel.source || '').toString().slice(0, 120);
  const targetName = t ? t.name : (rel.target || '').toString().slice(0, 120);
  if (!sourceName || !targetName) continue;
  const triple = {
    graph_id: cfg.graphId,
    fact: (rel.fact || `${sourceName} ${sanitizeRelation(rel.relation).toLowerCase().replace(/_/g, ' ')} ${targetName}.`).toString().slice(0, 600),
    fact_name: sanitizeRelation(rel.relation),
    source_node_name: sourceName,
    target_node_name: targetName,
  };
  if (s && s.uuid) triple.source_node_uuid = s.uuid;
  if (t && t.uuid) triple.target_node_uuid = t.uuid;
  if (s && !s.uuid && s.summary) triple.source_node_summary = s.summary;
  if (t && !t.uuid && t.summary) triple.target_node_summary = t.summary;
  triples.push(triple);
}

// Chunk the raw text into <=8000-char episodes on paragraph boundaries so the
// source document is also retrievable verbatim (and Zep runs its own
// extraction over it for anything our subagent missed).
const episodes = [];
const text = cfg.text || '';
let buf = '';
for (const para of text.split(/\n\n+/)) {
  if ((buf + '\n\n' + para).length > 8000 && buf) {
    episodes.push(buf);
    buf = para;
  } else {
    buf = buf ? buf + '\n\n' + para : para;
  }
}
if (buf.trim()) episodes.push(buf);

return [{
  json: {
    triples,
    episodes: episodes.map((data, idx) => ({
      data: data.slice(0, 9500),
      source_description: `${cfg.title} (part ${idx + 1}/${episodes.length}, via ${cfg.source})`,
    })),
    entityReport,
    counts: { entities: entityReport.length, relationships: triples.length, episodes: episodes.length },
  },
}];

// Transparent ingestion: report exactly what was sent to the graph.
// NOTE: Zep processes fact triples ASYNCHRONOUSLY — an accepted write returns
// {task_id, edge: null}. We therefore report relationships from the triples we
// sent (authoritative), and count a write as failed only when Zep returned
// neither an edge nor a task id.
const parseBody = (j) => {
  if (j && typeof j.data === 'string') {
    try { return JSON.parse(j.data); } catch { return {}; }
  }
  return j || {};
};
const cfg = $('Config').first().json;
const resolve = $('Resolve & Build Payloads').first().json;
const tripleResults = $('Write Fact Triple (Upsert)').all().map((i) => parseBody(i.json));
const episodeResults = $input.all().map((i) => parseBody(i.json));

const results = resolve.triples.map((t, i) => {
  const r = tripleResults[i] || {};
  return {
    ...t,
    ok: !!(r.edge || r.task_id),
    edgeUuid: r.edge ? r.edge.uuid : null,
  };
});
const failures = results.filter((r) => !r.ok).length;

// Synchronous responses (mock / future Zep) may include resolved nodes.
const byName = {};
for (const r of tripleResults) {
  for (const n of [r.source_node, r.target_node]) {
    if (n && n.name) byName[n.name.toLowerCase()] = n.uuid;
  }
}

const entities = resolve.entityReport.map((e) => ({
  name: e.name,
  type: e.type,
  summary: e.summary,
  status: e.status,
  uuid: e.uuid || byName[(e.name || '').toLowerCase()] || null,
}));

const relationships = results
  .filter((r) => r.ok)
  .map((r) => ({
    relation: r.fact_name,
    fact: r.fact,
    source: r.source_node_name,
    target: r.target_node_name,
    uuid: r.edgeUuid,
  }));

return [{
  json: {
    ok: true,
    graphId: cfg.graphId,
    title: cfg.title,
    entities,
    relationships,
    episodes: episodeResults.map((e) => e.uuid).filter(Boolean),
    stats: {
      entities: entities.length,
      created: entities.filter((e) => e.status === 'new').length,
      merged: entities.filter((e) => e.status === 'merged').length,
      relationships: relationships.length,
      episodes: episodeResults.length,
      failedWrites: failures,
    },
    message: `Ingested "${cfg.title}": ${entities.length} entities (${entities.filter((e) => e.status === 'merged').length} merged with existing nodes), ${relationships.length} relationships queued, ${episodeResults.length} episode(s). Zep continues processing asynchronously.`,
  },
}];
